#!/usr/bin/env python3
"""Write one COPY.BAT per batch of hdd/COPY-PLAN.md to hdd/batches/H<nn>.BAT.

On the Mac, after formatting diskette H<nn>:  cp hdd/batches/H<nn>.BAT /Volumes/H<nn>/COPY.BAT
On the machine (plain DOS prompt):            A:COPY
The file is written with CRLF line endings, uppercase, plain ASCII.
"""
import re
import sys
from pathlib import Path

repo = Path(__file__).resolve().parent.parent

# Decision 2026-10-23: compiled output is regenerated by the compiler, so it is not copied.
# Batches that end up with no XCOPY lines get no .BAT file.
SKIP_PREFIXES = ('C:\\CNC90\\MOD1\\COMP\\',)

listing = (repo / 'hdd' / 'LISTING.TXT').read_bytes().decode('cp437').replace('\r', '')
files_in = {}
_cur = None
for _line in listing.split('\n'):
    _m = re.match(r'\s*Directory di (\S+)', _line)
    if _m:
        _cur = _m.group(1).upper()
        continue
    _m = re.match(r'^(\S+)\s+(?:(\S+)\s+)?(\d+)\s+\d\d-\d\d-\d\d\s', _line)
    if _cur and _m and '<DIR>' not in _line:
        files_in.setdefault(_cur, []).append((_m.group(1) + ('.' + _m.group(2) if _m.group(2) else '')).upper())


def count_files(xcopy):
    """Files an `XCOPY C:\\DIR\\PATTERN A:\\...` line copies (one directory, no subfolders)."""
    src = re.match(r'XCOPY (\S+)', xcopy).group(1).upper()
    directory, pattern = src.rsplit('\\', 1)
    names = files_in.get(directory if directory != 'C:' else 'C:\\', [])
    if pattern == '*.*':
        return len(names)
    if '*' not in pattern:
        return names.count(pattern)
    assert pattern.endswith('*.*'), pattern
    stem = pattern[:-3]
    return sum(1 for n in names if n.split('.')[0].startswith(stem))


plan = (repo / 'hdd' / 'COPY-PLAN.md').read_text(encoding='utf-8')
out = repo / 'hdd' / 'batches'
out.mkdir(exist_ok=True)

def write_bat(label, title, files, cmds):
    lines = [
        '@ECHO OFF',
        f'REM {title}, label {label}: {files} files plus this COPY.BAT',
        'ECHO.',
        f'ECHO {title}: this diskette must be labelled {label}.',
        'VOL A:',
        'ECHO Ctrl+C to stop, any other key to copy.',
        'PAUSE > NUL',
        *cmds,
        'ECHO.',
        f'ECHO Done. Expected {files} files (+ COPY.BAT). Check the count below.',
        'DIR A: /S',
    ]
    text = '\r\n'.join(lines).upper() + '\r\n'
    (out / f'{label}.BAT').write_bytes(text.encode('ascii'))


for block in re.split(r'^## Batch ', plan, flags=re.M)[1:]:
    head = re.match(r'(\d+) → (H\d+)\s+\((\d+) files', block)
    batch, label, files = head.groups()
    cmds = re.search(r'```\n(.*?)```', block, re.S).group(1).strip().splitlines()
    cmds = [c.replace(' /V', '') for c in cmds]
    skipped = [c for c in cmds if c.upper().startswith(tuple('XCOPY ' + s for s in SKIP_PREFIXES))]
    cmds = [c for c in cmds if c not in skipped]
    if not skipped:
        assert sum(count_files(c) for c in cmds) == int(files), (label, files)
    files = str(sum(count_files(c) for c in cmds))
    if not cmds:
        stale = out / f'{label}.BAT'
        if stale.exists():
            stale.unlink()
        print(f'{label}  batch {batch}  skipped (regenerated output)', file=sys.stderr)
        continue
    write_bat(label, f'Batch {batch}', files, cmds)
    print(f'{label}.BAT  batch {batch}  {len(cmds)} XCOPY lines', file=sys.stderr)

# Extra diskette (not in the plan): files that exist on no captured diskette, found on 2026-10-23
# by comparing the rest of C: with every image in disks/ (name, size and date).
EXTRA = [
    ('H11', 'Extra', [c.replace('/', '\\') for c in (
        'XCOPY C:/CNC90/MOD1/TEMPOR/*.* A:/CNC90/MOD1/TEMPOR/',
        'XCOPY C:/CNC90/DRAWCNF.CNF A:/CNC90/',
        'XCOPY C:/AUTOEXEC.BAK A:/ROOT/',
        'XCOPY C:/CONFIG.BAK A:/ROOT/',
    )]),
]
for label, title, cmds in EXTRA:
    n = sum(count_files(c) for c in cmds)
    write_bat(label, title, n, cmds)
    print(f'{label}.BAT  {title}  {len(cmds)} XCOPY lines, {n} files', file=sys.stderr)
